BEGIN;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF ((SELECT count(*)=0 FROM platform.contacts)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|missing_context_hides_contacts'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000003102','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|missing_context_cannot_create'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000003101';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000003102','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|actor_required'; END $test$;
SET LOCAL app.actor_ref='phase5_test_actor';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF ((SELECT count(*)=3 AND bool_and(business_id='40000000-0000-4000-8000-000000003101') FROM platform.contacts)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|three_contacts_only_in_authorized_business'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (NOT EXISTS(SELECT 1 FROM platform.contacts WHERE id='50000000-0000-4000-8000-000000030101')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|other_business_profile_hidden'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000003202','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|other_business_instance_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000003102','synthetic-person-3@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|blocked_contact_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000003102','bad@example.invalid','invalid','Test'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '22023' THEN NULL; END; RAISE NOTICE 'P5PASS|invalid_identity_kind_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN SELECT count(*) INTO n FROM platform.audit_events; c:=platform.ensure_contact('40000000-0000-4000-8000-000000003102','phase5-new@example.invalid','synthetic','Original Synthetic Name'); IF (c=platform.ensure_contact('40000000-0000-4000-8000-000000003102','phase5-new@example.invalid','synthetic','Untrusted Changed Name')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT display_name='Original Synthetic Name' FROM platform.contacts WHERE id=c)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=n+1 FROM platform.audit_events)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=1 FROM platform.channel_identities WHERE jid='phase5-new@example.invalid')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|contact_create_replay_audit_and_profile_preservation'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (platform.ensure_contact('40000000-0000-4000-8000-000000003102','synthetic-person-1@example.invalid','synthetic','Test Contact')='50000000-0000-4000-8000-000000030001'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|shared_identity_does_not_merge_businesses'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000003201';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (platform.ensure_contact('40000000-0000-4000-8000-000000003202','synthetic-person-1@example.invalid','synthetic','Test Contact')='50000000-0000-4000-8000-000000030101'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF;IF (NOT EXISTS(SELECT 1 FROM platform.contacts WHERE id='50000000-0000-4000-8000-000000030001')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|same_identity_in_business_B_stays_separate'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000003101';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN INSERT INTO platform.contacts(business_id,display_name,status) VALUES('40000000-0000-4000-8000-000000003101','Test','active'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_insert_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE platform.contacts SET display_name='Forged'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_update_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN DELETE FROM platform.contacts; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_delete_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE platform.channel_identities SET contact_id='50000000-0000-4000-8000-000000030101'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_identity_rebinding_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN EXECUTE 'SET ROLE hospital_owner'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|runtime_cannot_assume_owner'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname IN ('platform','crm') AND (NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[] OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) ac WHERE ac.grantee=0 AND ac.privilege_type='EXECUTE')))) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|functions_have_fixed_path_and_no_public_execute'; END $test$;
ROLLBACK;
